#!/usr/bin/env bash

# Please run with existed data/snapshots/agnews_harmful.jsonl.
# data/snapshots/agnews_harmful.jsonl can be generated by run_agnews_harmful_snapshot.sh

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
BACKEND_DIR="${ROOT_DIR}/backend"

SAMPLES_JSONL="${ROOT_DIR}/data/snapshots/agnews_harmful.jsonl"
PROMPTS_DIR="${ROOT_DIR}/prompts"
OUT_DIR="${ROOT_DIR}/reports/rendered_prompts"
SNAPSHOT_META_PATH="${ROOT_DIR}/data/snapshots/dataset_snapshot_agnews_harmful.json"

RENDER_SCRIPT="${BACKEND_DIR}/app/cli/render_prompts_cli.py"

DEFAULT_PROMPT_PATHS=(
  "agnews_harmful/v1.txt"
  "agnews_harmful/v2.txt"
)

if [[ ! -f "${SAMPLES_JSONL}" ]]; then
  echo "Error: samples jsonl not found: ${SAMPLES_JSONL}"
  echo "Hint: run backend/scripts/run_agnews_harmful_snapshot.sh first to generate it."
  exit 1
fi

if [[ ! -f "${RENDER_SCRIPT}" ]]; then
  echo "Error: render script not found: ${RENDER_SCRIPT}"
  exit 1
fi

for prompt_rel_path in "${DEFAULT_PROMPT_PATHS[@]}"; do
  prompt_file="${PROMPTS_DIR}/${prompt_rel_path}"
  if [[ ! -f "${prompt_file}" ]]; then
    echo "Error: prompt file not found: ${prompt_file}"
    exit 1
  fi
done

export PYTHONPATH="${BACKEND_DIR}"

python "${RENDER_SCRIPT}" \
  "${DEFAULT_PROMPT_PATHS[@]}" \
  --prompts-root "${PROMPTS_DIR}" \
  --samples-jsonl-path "${SAMPLES_JSONL}" \
  --snapshot-meta-path "${SNAPSHOT_META_PATH}" \
  --rendered-prompts-dir "${OUT_DIR}" \
  "$@"

echo "Done. Rendered prompts written to: ${OUT_DIR}"
